join()指定的分隔符 说明 join() 可理解为直接变成字符串，默认逗号分隔 join(' '） 空连接 join(' ，')或者 join(' - ')或者 join(' 。') 中间这个逗号是手动添加的，也可以改成别的比如、。! -等等都可以 <pre><code>// join()
var a= ["00", "01", "02", "03", "04"]
var b=  a.join()      
console.log(b)
console.log( typeof b)
//打印结果  00,01,02,03,04
</code></pre> <pre><code>// join('')
var a= ["00", "01", "02", "03", "04"]
var b=  a.join('')      
console.log(b)
console.log( typeof b)
//打印结果  0001020304
</code></pre> <pre><code>// join(',')
var a= ["00", "01", "02", "03", "04"]
var b=  a.join(',')      
console.log(b)
console.log( typeof b)
//打印结果  00,01,02,03,04

或者

// join('-')
var a= ["00", "01", "02", "03", "04"]
var b=  a.join('-')      
console.log(b)
console.log( typeof b)
//打印结果  00-01-02-03-04

或者
// join('！')
var a= ["00", "01", "02", "03", "04"]
var b=  a.join('!')      
console.log(b)
console.log( typeof b)
//打印结果 00!01!02!03!04
</code></pre>
